import React, { useState } from "react";
import { OrgSwitcher, abbreviateOrg, abbreviateCampus, mobileLabel }
  from "../../../../components/org-switcher/org-switcher.jsx";

const DEMO_ORGS = [
  { id: "gcc-west",  orgName: "Grace Community Church",    campusName: "West" },
  { id: "gcc-east",  orgName: "Grace Community Church",    campusName: "East" },
  { id: "gcc-ga",    orgName: "Grace Community Church",    campusName: "Georgia" },
  { id: "ncc-nn",    orgName: "Nashville Christian Church", campusName: "Nashville North" },
  { id: "ncc-ns",    orgName: "Nashville Christian Church", campusName: "Nashville South" },
  { id: "npc",       orgName: "Northpoint Church",          campusName: "" },
  { id: "npc-kn",    orgName: "Northpoint Church",          campusName: "Knoxville" },
  { id: "ele-mc",    orgName: "Elevation",                  campusName: "Main Campus" },
  { id: "chh-north", orgName: "Church of the Highlands",    campusName: "North" },
  { id: "crc-dt",    orgName: "Crossroads Church",          campusName: "Downtown" },
];

export default {
  title: "Library/OrgSwitcher",
  component: OrgSwitcher,
  parameters: {
    docs: { description: { component: "**PLACEHOLDER** — awaiting Figma node + spec review. See `org-switcher-spec.md`." } },
    layout: "padded",
  },
  argTypes: {
    orgName:    { control: "text",    description: "Full organisation name" },
    campusName: { control: "text",    description: "Full campus / sub-org name (empty if none)" },
    disabled:   { control: "boolean", description: "True for single-org users — trigger renders but panel does not open" },
    mobile:     { control: "boolean", description: "Force mobile abbreviated display regardless of viewport" },
  },
};

// ── Playground ────────────────────────────────────────────────────────────────
function PlaygroundTemplate(args) {
  const [activeId, setActiveId] = useState("gcc-west");
  const active = DEMO_ORGS.find(o => o.id === activeId) || DEMO_ORGS[0];
  return (
    <div style={{ fontFamily: "'Red Hat Text', sans-serif", padding: 24 }}>
      <OrgSwitcher
        {...args}
        orgName={active.orgName}
        campusName={active.campusName}
        orgs={DEMO_ORGS}
        onOrgChange={id => setActiveId(id)}
      />
    </div>
  );
}

export const Playground = PlaygroundTemplate.bind({});
Playground.args = { disabled: false, mobile: false };
Playground.storyName = "Playground";

// ── Desktop display ────────────────────────────────────────────────────────────
export const Desktop = () => (
  <div style={{ fontFamily: "'Red Hat Text', sans-serif", display: "flex", flexDirection: "column", gap: 12, padding: 24 }}>
    {[
      { orgName: "Grace Community Church", campusName: "West" },
      { orgName: "Nashville Christian Church", campusName: "Nashville North" },
      { orgName: "Northpoint Church", campusName: "" },
      { orgName: "Elevation", campusName: "Main Campus" },
    ].map((o, i) => (
      <OrgSwitcher key={i} orgName={o.orgName} campusName={o.campusName} orgs={DEMO_ORGS} />
    ))}
  </div>
);
Desktop.storyName = "Desktop — full names";

// ── Mobile display ─────────────────────────────────────────────────────────────
export const Mobile = () => (
  <div style={{ fontFamily: "'Red Hat Text', sans-serif", display: "flex", flexDirection: "column", gap: 12, padding: 24 }}>
    {[
      { orgName: "Grace Community Church", campusName: "West" },
      { orgName: "Nashville Christian Church", campusName: "Nashville North" },
      { orgName: "Northpoint Church", campusName: "" },
      { orgName: "Elevation", campusName: "Main Campus" },
      { orgName: "Church of the Highlands", campusName: "North" },
      { orgName: "Knoxville Sanctuary", campusName: "East" },
    ].map((o, i) => (
      <OrgSwitcher key={i} mobile orgName={o.orgName} campusName={o.campusName} orgs={DEMO_ORGS} />
    ))}
  </div>
);
Mobile.storyName = "Mobile — abbreviated";

// ── Abbreviation showcase ──────────────────────────────────────────────────────
const ABBR_EXAMPLES = [
  ["Grace Community Church",    "West"],
  ["Grace Community Church",    "East"],
  ["Grace Community Church",    "Georgia"],
  ["Nashville Christian Church","Nashville North"],
  ["Nashville Christian Church","Nashville South"],
  ["Northpoint Church",         ""],
  ["Northpoint Church",         "Knoxville"],
  ["Crossroads Church",         "Downtown"],
  ["Elevation",                 "Main Campus"],
  ["Church of the Highlands",   "North"],
  ["Knoxville Sanctuary",       "East"],
];

export const AbbreviationShowcase = () => (
  <div style={{ fontFamily: "'Red Hat Text', sans-serif", padding: 24 }}>
    <p style={{ fontSize: 12, color: "#71717a", marginBottom: 16 }}>
      Abbreviation output per spec Appendix A. Desktop (full) vs mobile (abbreviated).
    </p>
    <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
      <thead>
        <tr style={{ borderBottom: "2px solid #e5e7eb" }}>
          <th style={{ textAlign: "left", padding: "6px 8px", color: "#71717a", fontWeight: 600 }}>Org name</th>
          <th style={{ textAlign: "left", padding: "6px 8px", color: "#71717a", fontWeight: 600 }}>Campus</th>
          <th style={{ textAlign: "left", padding: "6px 8px", color: "#3555a0", fontWeight: 700 }}>Mobile label</th>
          <th style={{ textAlign: "left", padding: "6px 8px", color: "#71717a", fontWeight: 600 }}>Org abbr.</th>
          <th style={{ textAlign: "left", padding: "6px 8px", color: "#71717a", fontWeight: 600 }}>Campus abbr.</th>
        </tr>
      </thead>
      <tbody>
        {ABBR_EXAMPLES.map(([org, campus], i) => (
          <tr key={i} style={{ borderBottom: "1px solid #f5f5f5" }}>
            <td style={{ padding: "7px 8px" }}>{org}</td>
            <td style={{ padding: "7px 8px", color: "#71717a" }}>{campus || "—"}</td>
            <td style={{ padding: "7px 8px", fontWeight: 700, fontFamily: "monospace", color: "#363636" }}>
              {mobileLabel(org, campus)}
            </td>
            <td style={{ padding: "7px 8px", fontFamily: "monospace", color: "#71717a" }}>
              {abbreviateOrg(org)}
            </td>
            <td style={{ padding: "7px 8px", fontFamily: "monospace", color: "#71717a" }}>
              {campus ? abbreviateCampus(campus) : "—"}
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  </div>
);
AbbreviationShowcase.storyName = "Abbreviation Showcase (Appendix A)";

